class Solution {
public:
    int colorTheGrid(int m, int n) {
        const int MOD = 1e9 + 7;
        vector<vector<int>> validCols;
        vector<int> curr;
        auto gen = [&](auto& self) -> void {
            if (curr.size() == m) {
                validCols.push_back(curr);
                return;
            }
            for (int c = 0; c < 3; c++) {
                if (curr.empty() || curr.back() != c) {
                    curr.push_back(c);
                    self(self);
                    curr.pop_back();
                }
            }
        };
        gen(gen);

        int S = validCols.size();
        vector<vector<int>> adj(S);
        for (int i = 0; i < S; i++) {
            for (int j = 0; j < S; j++) {
                bool ok = true;
                for (int r = 0; r < m; r++) {
                    if (validCols[i][r] == validCols[j][r]) {
                        ok = false;
                        break;
                    }
                }
                if (ok) adj[i].push_back(j);
            }
        }

        vector<int> dp(S, 1);
        for (int col = 1; col < n; col++) {
            vector<int> newDp(S, 0);
            for (int i = 0; i < S; i++) {
                if (!dp[i]) continue;
                for (int nxt : adj[i]) {
                    newDp[nxt] = (newDp[nxt] + dp[i]) % MOD;
                }
            }
            dp = newDp;
        }
        long long ans = 0;
        for (int x : dp) ans = (ans + x) % MOD;
        return ans;
    }
};

class Solution {
    public int colorTheGrid(int m, int n) {
        final int MOD = 1_000_000_007;
        java.util.List<int[]> validCols = new java.util.ArrayList<>();
        generate(m, new int[m], 0, validCols);
        int S = validCols.size();
        java.util.List<Integer>[] adj = new java.util.ArrayList[S];
        for (int i = 0; i < S; i++) adj[i] = new java.util.ArrayList<>();
        for (int i = 0; i < S; i++) {
            for (int j = 0; j < S; j++) {
                boolean ok = true;
                for (int r = 0; r < m; r++) {
                    if (validCols.get(i)[r] == validCols.get(j)[r]) {
                        ok = false;
                        break;
                    }
                }
                if (ok) adj[i].add(j);
            }
        }
        int[] dp = new int[S];
        java.util.Arrays.fill(dp, 1);
        for (int col = 1; col < n; col++) {
            int[] newDp = new int[S];
            for (int i = 0; i < S; i++) {
                if (dp[i] == 0) continue;
                for (int nxt : adj[i]) {
                    newDp[nxt] = (newDp[nxt] + dp[i]) % MOD;
                }
            }
            dp = newDp;
        }
        long ans = 0;
        for (int x : dp) ans = (ans + x) % MOD;
        return (int) ans;
    }

    private void generate(int m, int[] curr, int idx, java.util.List<int[]> res) {
        if (idx == m) {
            res.add(curr.clone());
            return;
        }
        for (int c = 0; c < 3; c++) {
            if (idx == 0 || curr[idx - 1] != c) {
                curr[idx] = c;
                generate(m, curr, idx + 1, res);
            }
        }
    }
}

var colorTheGrid = function(m, n) {
  const MOD = 1000000007;
  const validCols = [];
  const gen = (curr) => {
    if (curr.length === m) {
      validCols.push([...curr]);
      return;
    }
    for (let c = 0; c < 3; c++) {
      if (curr.length === 0 || curr[curr.length - 1] !== c) {
        curr.push(c);
        gen(curr);
        curr.pop();
      }
    }
  };
  gen([]);

  const S = validCols.length;
  const adj = Array.from({ length: S }, () => []);
  for (let i = 0; i < S; i++) {
    for (let j = 0; j < S; j++) {
      let ok = true;
      for (let r = 0; r < m; r++) {
        if (validCols[i][r] === validCols[j][r]) {
          ok = false;
          break;
        }
      }
      if (ok) adj[i].push(j);
    }
  }

  let dp = new Array(S).fill(1);
  for (let col = 1; col < n; col++) {
    const newDp = new Array(S).fill(0);
    for (let i = 0; i < S; i++) {
      if (!dp[i]) continue;
      for (const nxt of adj[i]) {
        newDp[nxt] = (newDp[nxt] + dp[i]) % MOD;
      }
    }
    dp = newDp;
  }
  return dp.reduce((acc, x) => (acc + x) % MOD, 0);
};
